/* Mastermind — Pure CSS — generated */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Segoe UI',system-ui,sans-serif;background:#1a1a2e;color:#e0e0e0;min-height:100vh;display:flex;justify-content:center}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
.g{max-width:480px;width:100%;padding:20px;text-align:center}
h1{font-size:2rem;color:#fff;letter-spacing:2px;margin-bottom:2px}
.sub{font-size:.8rem;color:#555;margin-bottom:20px}
h2{font-size:1.1rem;color:#ccc;margin-bottom:10px}
.hint{font-size:.8rem;color:#777;margin-bottom:14px}
.peg-red,.opt-red{background:#E74C3C}
.peg-orange,.opt-orange{background:#E67E22}
.peg-yellow,.opt-yellow{background:#F1C40F}
.peg-green,.opt-green{background:#27AE60}
.peg-blue,.opt-blue{background:#2980B9}
.peg-purple,.opt-purple{background:#8E44AD}
.ps{width:44px;height:44px;border-radius:50%;background:#2a2a4a;display:inline-flex;align-items:center;justify-content:center;position:relative;overflow:hidden;margin:0 4px}
.ep{font-size:1rem;color:#555}
.peg{position:absolute;inset:0;border-radius:50%;display:none}
.pk{margin-bottom:10px}
.pl{font-size:.75rem;color:#666;margin-bottom:3px}
.opts,.mp{display:flex;gap:6px;justify-content:center}
.opt{width:32px;height:32px;border-radius:50%;cursor:pointer;border:3px solid transparent;transition:transform .12s,border-color .12s}
.opt:hover{transform:scale(1.12);border-color:rgba(255,255,255,.4)}
.mi{width:20px;height:20px;border-width:2px}
.btn{display:none;margin:12px auto;padding:8px 24px;background:#16213e;color:#fff;border:2px solid #0f3460;border-radius:8px;cursor:pointer;font-size:.95rem;text-decoration:none;width:fit-content;transition:background .15s}
.btn:hover{background:#0f3460}
.sd{display:flex;justify-content:center;gap:8px;margin-bottom:16px}
.row{display:none;flex-direction:column;align-items:center;background:#16213e;border-radius:10px;padding:10px;margin-bottom:8px}
.rn{font-size:.7rem;color:#444;margin-bottom:4px}
.gd{display:flex;justify-content:center;margin-bottom:6px}
.rp{display:flex;gap:14px;justify-content:center;margin-bottom:6px}
.mp{display:grid;grid-template-columns:repeat(3,1fr);gap:3px}
.fb{display:none;gap:6px;justify-content:center;align-items:center;margin-top:8px}
.fbb{display:none;width:20px;height:20px;border-radius:50%;background:#1a1a1a;border:3px solid #fff;box-shadow:0 0 0 1px rgba(255,255,255,0.3)}
.ww{display:inline-flex;counter-reset:wp;align-items:center}
.wh{display:none;counter-increment:wp}
.sh{display:flex;justify-content:center;gap:8px;margin-bottom:16px}
.hp{width:40px;height:40px;border-radius:50%;background:#0f3460;display:flex;align-items:center;justify-content:center;font-size:1rem;color:#444}
.go{display:none}
.win,.loss{display:none}
.win h2{color:#27AE60}
.loss h2{color:#E74C3C}
.rev{display:flex;justify-content:center;gap:8px;margin:14px 0}
.nb{display:inline-block !important}
@counter-style wempty{system:cyclic;symbols:'';suffix:''}
@counter-style wdots{system:symbolic;symbols:'\25CB';suffix:'';range:1 4;fallback:wempty}
.ww::after{content:counter(wp,wdots);font-size:20px;letter-spacing:2px;color:rgba(255,255,255,0.5)}
.setup{display:block}.play{display:none}
#lock-in:checked~.g .setup{display:none}
#lock-in:checked~.g .play{display:block}
